<script setup>
import AppSelect from '../../shared/components/AppSelect.vue';
import { computed, reactive } from 'vue';
import AccountPicker from '../finance/AccountPicker.vue';
import {useAccountLookup} from '../../shared/api/account-lookup.js';
const lookup=useAccountLookup();
import ReportModal from './ReportModal.vue';
import { emptyFilters,preset,descendantOf,reportKinds,statusLabels,reportFilterFlags,normalizeReportFilters } from './report-model.js';
const props=defineProps({filters:Object,options:Object}); const emit=defineEmits(['close','apply']);
const filterFlags=computed(()=>reportFilterFlags(props.options));
const draft=reactive(normalizeReportFilters(props.filters,props.options)); const accounts=computed(()=>props.options.accounts??[]);
const selected=accounts.value.find((a)=>Number(a.id)===Number(draft.agent_id));
const selection=reactive({main:selected?.type==='main_agent'?selected.id:'',branch:selected && selected.type!=='main_agent'?selected.id:''});
function changeMain(){selection.branch='';draft.agent_id=selection.main;draft.pos_id='';}
function changeBranch(){draft.agent_id=selection.branch||selection.main;draft.pos_id='';}
function reset(){Object.assign(draft,emptyFilters());selection.main='';selection.branch='';}
const branches=computed(()=>accounts.value.filter((a)=>['sub_agent','sub_branch'].includes(a.type)&&descendantOf(accounts.value,a.id,selection.main)));
const points=computed(()=>accounts.value.filter((a)=>a.type==='pos'&&descendantOf(accounts.value,a.id,draft.agent_id)));
const products=computed(()=>props.options.products.filter((p)=>(!draft.provider_id||Number(p.provider_id)===Number(draft.provider_id))&&p.currency===draft.currency));
const kinds=computed(()=>reportKinds.filter(([id])=>props.options.sections.some((s)=>s.id.split('-')[0]===id)));
</script>
<template><ReportModal title="إعداد التقرير" @close="emit('close')"><form @submit.prevent="emit('apply',{...draft})"><div class="report-filters"><div class="cardhead"><button type="button" class="btn ghost small" @click="reset">إعادة ضبط</button></div><div class="report-presets"><button v-for="[id,label] in [['today','اليوم'],['week','آخر 7 أيام'],['month','هذا الشهر'],['all','كل الفترات']]" :key="id" type="button" class="btn small" @click="Object.assign(draft,preset(id))">{{label}}</button></div><div class="report-filter-grid"><label>من<input lang="en" type="date" v-model="draft.from" :max="draft.to||undefined"/></label><label>إلى<input lang="en" type="date" v-model="draft.to" :min="draft.from||undefined"/></label><label>نوع التقرير<AppSelect v-model="draft.kind"><option value="all">التقرير الشامل</option><option v-for="[id,label] in kinds" :key="id" :value="id">{{label}}</option></AppSelect></label><label v-if="filterFlags.accounts&&(options.account_kinds?.main_agent||accounts.some(a=>a.type==='main_agent'))">الوكيل الرئيسي<AccountPicker v-model="selection.main" :vm="lookup" :parameters="{context:'reports',account_type:'main_agent'}" label="الوكيل الرئيسي" @update:model-value="changeMain"/></label><label v-if="filterFlags.accounts&&(options.account_kinds?.sub_agent||options.account_kinds?.sub_branch||accounts.some(a=>['sub_agent','sub_branch'].includes(a.type)))">الفرع / الفرع الفرعي<AccountPicker v-model="selection.branch" :vm="lookup" :parameters="{context:'reports',account_types:['sub_agent','sub_branch'],ancestor_id:selection.main}" label="الفرع / الفرع الفرعي" @update:model-value="changeBranch"/></label><label v-if="filterFlags.accounts">نقطة البيع<AccountPicker v-model="draft.pos_id" :vm="lookup" :parameters="{context:'reports',account_type:'pos',ancestor_id:draft.agent_id}" label="نقطة البيع"/></label><label v-if="filterFlags.products">الفئة<AppSelect v-model="draft.product_id"><option value="">الكل ضمن نطاقي</option><option v-for="p in products" :key="p.id" :value="p.id">{{p.name}}</option></AppSelect></label><label v-if="filterFlags.providers">الشركة<AppSelect v-model="draft.provider_id" @change="draft.product_id=''"><option value="">الكل ضمن نطاقي</option><option v-for="p in options.providers" :key="p.id" :value="p.id">{{p.name}}</option></AppSelect></label><label v-if="filterFlags.cities">المحافظة<AppSelect v-model="draft.city"><option value="">الكل ضمن نطاقي</option><option v-for="city in options.cities" :key="city">{{city}}</option></AppSelect></label><label v-if="filterFlags.status">حالة البيع<AppSelect v-model="draft.status"><option value="">الكل ضمن نطاقي</option><option v-for="status in ['Print Requested','Print Failed','Printed','Reprinted','Reprint Requested','Delivered']" :key="status" :value="status">{{statusLabels[status]}}</option></AppSelect></label></div><p v-if="filterFlags.products&&filterFlags.providers&&filterFlags.status" class="help">التاريخ يرشح الحركات. الحالة تخص المبيعات فقط. الفئة والشركة يرشحان المبيعات والمخزون والأسعار. المخزون والشبكة والإعدادات لقطات حالية.</p></div><div class="formfoot"><button type="button" class="btn" @click="emit('close')">إلغاء</button><button class="btn primary">تطبيق إعداد التقرير</button></div></form></ReportModal></template>
